const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const getInfo = (obj) => new Promise((resolve, reject) => obj.getInfo(resolve, reject));

  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-122.2, 36.9, -121.2, 37.7], null, false);
  const juneStart = '2020-06-01';
  const juneEnd = '2020-06-30';
  const augStart = '2020-08-20';
  const augEnd = '2020-08-30';

  // Cloud masks and composites
  function maskS2(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return img.updateMask(mask).copyProperties(img, ['system:time_start', 'CLOUDY_PIXEL_PERCENTAGE']);
  }
  function s2Composite(start, end, geom) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geom).filterDate(start, end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
      .map(maskS2);
    return col;
  }
  function maskL8(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0)  // Cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0))       // Cloud shadow
      .and(qa.bitwiseAnd(1 << 1).eq(0))       // Dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0));      // Cirrus
    const optical = image.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
      .multiply(0.0000275).add(-0.2);
    return image.addBands(optical, null, true).updateMask(mask)
      .copyProperties(image, ['system:time_start', 'CLOUD_COVER']);
  }
  function l8Composite(start, end, geom) {
    const col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(geom).filterDate(start, end).map(maskL8);
    return col;
  }

  async function getCompositeWithFallback(start, end, geom) {
    let provider = 'S2';
    let col = s2Composite(start, end, geom);
    let size = await getInfo(col.size());
    if (size === 0) {
      provider = 'L8';
      col = l8Composite(start, end, geom);
      size = await getInfo(col.size());
    }
    if (size === 0) return {img: null, size: 0, provider};
    const comp = col.median().clip(geom);
    let nbr;
    if (provider === 'S2') {
      nbr = comp.normalizedDifference(['B8','B12']).rename('NBR');
    } else {
      nbr = comp.normalizedDifference(['SR_B5','SR_B7']).rename('NBR');
    }
    const img = comp.addBands(nbr);
    return {img, size, provider};
  }

  try {
    // 2. Data Acquisition & Check
    const june = await getCompositeWithFallback(juneStart, juneEnd, region);
    const aug = await getCompositeWithFallback(augStart, augEnd, region);

    if (june.size === 0 || aug.size === 0) {
      console.log(`June Images: ${june.size}`);
      console.log(`Aug Images: ${aug.size}`);
      console.log('C1');
      return;
    }

    // 3. Processing & Valid pixel checks
    const scale = 1000;
    const totalCount = await getInfo(ee.Image.constant(1).rename('one').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region, scale: scale, maxPixels: 1e9
    }).get('one'));

    const juneCount = await getInfo(june.img.select('NBR').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region, scale: scale, maxPixels: 1e9
    }).get('NBR'));
    const augCount = await getInfo(aug.img.select('NBR').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region, scale: scale, maxPixels: 1e9
    }).get('NBR'));

    if (!juneCount || !augCount || juneCount === 0 || augCount === 0) {
      console.log(`June Images: ${june.size}, Valid px: ${juneCount || 0}/${totalCount}`);
      console.log(`Aug Images: ${aug.size}, Valid px: ${augCount || 0}/${totalCount}`);
      console.log('C2');
      return;
    }

    // 4. Calculations
    const juneNBRmean = await getInfo(june.img.select('NBR').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region, scale: scale, maxPixels: 1e9
    }).get('NBR'));
    const augNBRmean = await getInfo(aug.img.select('NBR').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region, scale: scale, maxPixels: 1e9
    }).get('NBR'));

    const dNBR = ee.Image(june.img.select('NBR').subtract(aug.img.select('NBR'))).rename('dNBR');

    const areaImg = ee.Image.pixelArea().divide(1e6).rename('area_km2');
    const burnedJuneMask = june.img.select('NBR').lt(0.1);
    const burnedAugMask = aug.img.select('NBR').lt(0.1);
    const newBurnMask = dNBR.gt(0.27);

    const areaJune = await getInfo(areaImg.updateMask(burnedJuneMask).reduceRegion({
      reducer: ee.Reducer.sum(), geometry: region, scale: scale, maxPixels: 1e9
    }).get('area_km2'));
    const areaAug = await getInfo(areaImg.updateMask(burnedAugMask).reduceRegion({
      reducer: ee.Reducer.sum(), geometry: region, scale: scale, maxPixels: 1e9
    }).get('area_km2'));
    const areaNewBurn = await getInfo(areaImg.updateMask(newBurnMask).reduceRegion({
      reducer: ee.Reducer.sum(), geometry: region, scale: scale, maxPixels: 1e9
    }).get('area_km2'));
    const regionArea = await getInfo(areaImg.reduceRegion({
      reducer: ee.Reducer.sum(), geometry: region, scale: scale, maxPixels: 1e9
    }).get('area_km2'));

    // 5. Validation & Final Answer
    const invalid = [juneNBRmean, augNBRmean, areaJune, areaAug, areaNewBurn, regionArea]
      .some(v => v === null || v === undefined || isNaN(v));
    if (invalid) {
      console.log('Calculation invalid (null/NaN).');
      console.log('C3');
      return;
    }

    console.log(`Region km²: ${regionArea.toFixed(0)}`);
    console.log(`June Images: ${june.size}, Valid px: ${juneCount}/${totalCount}, NBR(mean): ${juneNBRmean.toFixed(3)}`);
    console.log(`Aug Images: ${aug.size}, Valid px: ${augCount}/${totalCount}, NBR(mean): ${augNBRmean.toFixed(3)}`);
    console.log(`Burn area NBR<0.1 (km²): June=${(areaJune||0).toFixed(1)}, Aug=${(areaAug||0).toFixed(1)}`);
    console.log(`New burn (dNBR>0.27) km²: ${((areaNewBurn)||0).toFixed(1)}`);

    const expanded = ((areaAug - areaJune) > 1.0) || (areaNewBurn > 1.0);
    console.log(expanded ? 'A' : 'B');
  } catch (e) {
    console.log(`Error: ${e.message || e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
